/**
 * Busca la venta por código y decide qué corresponde. Igual que en A3, este es
 * el único nodo que piensa.
 *
 * Los cuatro desenlaces posibles, y por qué existe cada uno:
 *
 *   no_existe     · Pía se equivocó de número, o el comprobante nunca llegó.
 *                   Se le dice, y no se escribe nada.
 *   ya_procesado  · Mandó el comando dos veces. LA GUARDA IMPORTANTE: sin esto,
 *                   la clienta recibiría dos accesos y dos mails de bienvenida.
 *   confirmar     · Estado a `confirmado`, se fija hasta cuándo tiene acceso y
 *                   se dispara el onboarding (A4).
 *   rechazar      · Estado a `rechazado` y se le escribe a la clienta pidiendo
 *                   que aclare. Nunca se la deja sin respuesta.
 */
// El nodo Configuración deja pasar los campos que mandó el router (viene con
// "Include Other Input Fields" activado), así que acá conviven las constantes
// del negocio y el comando que escribió Pía.
const cfg = $('Configuración').first().json;

const codigo = String(cfg.comandoCodigo ?? '').padStart(4, '0');
const verbo = String(cfg.comandoVerbo ?? '').toUpperCase();

const filas = $input.all()
  .map((i) => i.json)
  .filter((f) => f && f.codigo);

const fila = filas.find((f) => String(f.codigo).padStart(4, '0') === codigo) ?? null;

if (!fila) {
  return [{ json: { accion: 'no_existe', codigo, verbo } }];
}

const estado = String(fila.estado ?? '').toLowerCase();
if (estado !== 'pendiente') {
  return [{ json: { accion: 'ya_procesado', codigo, verbo, estadoActual: estado, nombre: fila.nombre } }];
}

// El monto se deriva del plan, no se le pide a nadie que lo escriba: el precio
// vive en src/lib/products.ts y acá sólo se refleja. Si el plan quedó vacío,
// queda vacío el monto también — es preferible un hueco visible a un número
// inventado en la fila de una venta.
const montos = {
  'nivel-mensual': cfg.precioNivel,
  'pack-3-niveles': cfg.precioPack,
};

// Hasta cuándo tiene acceso. Empieza AHORA: no hay fecha de inicio de grupo que
// esperar, así que el reloj arranca en este mismo momento.
//
// Un nivel dura 28 días y hay que renovarlo; el pack de 3 se paga una sola vez y
// da la ventana completa. Esta fecha es la que consume A27 para los recordatorios
// de renovación: si queda vacía, nadie avisa nada.
const vence = new Date();
if (fila.plan === 'pack-3-niveles') {
  vence.setMonth(vence.getMonth() + Number(cfg.ventanaPackMeses));
} else {
  vence.setDate(vence.getDate() + Number(cfg.accesoDias));
}

const actualizada = {
  ...fila,
  codigo,
  estado: verbo === 'OK' ? 'confirmado' : 'rechazado',
  monto: verbo === 'OK' ? (montos[fila.plan] ?? fila.monto ?? '') : (fila.monto ?? ''),
  acceso_vence: verbo === 'OK' ? vence.toISOString().slice(0, 10) : '',
  renovaciones: fila.renovaciones ?? 0,
};

// row_number lo agrega el nodo de Google Sheets al leer; si se lo mandamos de
// vuelta en la escritura, aparece como una columna nueva en la planilla.
delete actualizada.row_number;

return [{
  json: {
    accion: verbo === 'OK' ? 'confirmar' : 'rechazar',
    codigo,
    verbo,
    fila: actualizada,
  },
}];

